// src/pages/Community.js

import { useNavigate } from "react-router-dom";

const meetings = [
  {
    id: 1,
    title: "노르웨이의 숲 독서모임",
    time: "오늘 19:00",
    members: "6/8명",
    mood: "깊게 토론해요",
  },

  {
    id: 2,
    title: "데미안 함께 읽기",
    time: "내일 20:00",
    members: "4/6명",
    mood: "함께 이야기해요",
  },
];

function Community() {
  const navigate = useNavigate();

  return (
    <div className="page">
      {/* 상단 */}
      <div className="top-bar">
        <div className="logo">
          READLY
        </div>
      </div>

      {/* 안내 */}
      <div className="community-banner">
        ⏰ 모임 시작 10분 전까지
        참여할 수 있어요!
      </div>

      {/* 모임 리스트 */}
      {meetings.map((meeting) => (
        <div
          className="meeting-card"
          key={meeting.id}
        >
          <div className="meeting-top">
            <div>
              <div className="meeting-title">
                {meeting.title}
              </div>

              <div className="meeting-time">
                {meeting.time}
              </div>
            </div>

            <div className="meeting-badge">
              {meeting.mood}
            </div>
          </div>

          <div className="meeting-footer">
            <span>{meeting.members}</span>

            <button
              className="join-btn"
              onClick={() =>
                navigate("/meeting")
              }
            >
              참여하기
            </button>
          </div>
        </div>
      ))}
    </div>
  );
}

export default Community;
